/**
 * Cursor cloud agents as an extension. Mount it and the agent can hand
 * coding work to Cursor cloud agents and steer a fleet of them:
 *
 * ```ts
 * // agent/extensions/cloud.ts
 * import cursorCloudAgents from "@grok/agent-sdk/extensions/cursor-cloud-agents";
 *
 * export default cursorCloudAgents({
 *   cloud: { repos: [{ url: "https://github.com/acme/api" }], autoCreatePR: true },
 * });
 * ```
 *
 * Contributes `cloud__launch`, `cloud__get`, `cloud__dump`, `cloud__reply`,
 * `cloud__cancel`, `cloud__list` and the `cloud__handoff` skill (the
 * namespace is the mount filename), the action vocabulary Sand's CloudAgent
 * tool uses, over the same backend calls: launches through the v1 Cloud
 * Agents API, everything else through the BackgroundComposerService RPCs,
 * all under the serve host's Cursor API key (`CURSOR_API_KEY`, key file, or
 * `login`). Each launched agent stays bound to the principal that launched
 * it, and launches go to the configured repositories. `channels` limits
 * launch, reply, and cancel to sessions on those channel ids, so a channel
 * whose input is untrusted (an alert webhook) cannot start or steer an agent.
 * The tools run on the serve host, so they need the local runtime.
 *
 * The `cloud__cloud-agent-stop-watch` reminder wakes the conversation that
 * launched an agent once that agent stops (`watchStops`). The host polls the
 * agent; no model turn runs until the one wake.
 */
import * as z from "zod/v4";
import { defineExtension } from "../../extensions.js";
export { followUpCloudAgent, getCloudAgent, getCloudEnvironment, launchCloudAgent, listCloudEnvironmentsNamed, } from "./lib/launch-agent.js";
export { launchRepos } from "./lib/repos.js";
const repo = z.object({
    url: z.string().url(),
    startingRef: z.string().optional(),
    prUrl: z.string().url().optional(),
});
const repos = z.array(repo);
/** A `repos` function; each call's result is validated like a static list. */
const reposFunction = z
    .custom((value) => typeof value === "function")
    .transform((fn) => () => repos.parse(fn()));
const mcpServer = z.union([
    z.strictObject({
        name: z.string().min(1),
        type: z.literal("stdio").optional(),
        command: z.string().min(1),
        args: z.array(z.string()).optional(),
        env: z.record(z.string(), z.string()).optional(),
    }),
    z.strictObject({
        name: z.string().min(1),
        type: z.enum(["http", "sse"]).optional(),
        url: z.string().url(),
        headers: z.record(z.string(), z.string()).optional(),
    }),
]);
const cloud = z.object({
    env: z
        .discriminatedUnion("type", [
        z.object({ type: z.literal("cloud"), name: z.string().optional() }),
        z.object({ type: z.literal("pool"), name: z.string().optional() }),
        z.object({ type: z.literal("machine"), name: z.string().optional() }),
    ])
        .optional(),
    repos: z.union([repos, reposFunction]).optional(),
    workOnCurrentBranch: z.boolean().optional(),
    autoCreatePR: z.boolean().optional(),
    skipReviewerRequest: z.boolean().optional(),
    envVars: z.record(z.string(), z.string()).optional(),
    mcpServers: z.array(mcpServer).optional(),
    teamMcpServers: z.array(z.string().trim().min(1).max(255)).min(1).max(50).optional(),
});
const model = z.union([
    z.string().min(1),
    z.object({
        id: z.string().min(1),
        params: z.array(z.object({ id: z.string(), value: z.string() })).optional(),
    }),
]);
const config = z
    .object({
    cloud: cloud.prefault({}),
    model: model.optional(),
    needsApproval: z.boolean().optional(),
    channels: z.array(z.string().min(1)).optional(),
    refuseSession: z
        .custom((value) => typeof value === "function")
        .optional(),
    apiKey: z.string().optional(),
    watchStops: z.boolean().default(true),
})
    .prefault({})
    .transform((options) => ({
    ...options,
    needsApproval: options.needsApproval ?? options.cloud.repos === undefined,
}));
const cursorCloudAgents = defineExtension({
    root: import.meta.dirname,
    description: "Launch, steer, and monitor Cursor cloud agents.",
    config,
});
export default cursorCloudAgents;
